1179 | /* ==========================================
1180 |    CANVAS BACKGROUND — NETWORK PARTICLES
1181 |    ========================================== */
1182 | function initCanvas() {
1183 |   const canvas = document.getElementById('bg-canvas');
1184 |   const ctx = canvas.getContext('2d');
1185 |   let W, H, particles = [];
1186 | 
1187 |   function resize() {
1188 |     W = canvas.width = window.innerWidth;
1189 |     H = canvas.height = window.innerHeight;
1190 |   }
1191 |   resize();
1192 |   window.addEventListener('resize', resize);
1193 | 
1194 |   const N = 70;
1195 |   for (let i = 0; i < N; i++) {
1196 |     particles.push({
1197 |       x: Math.random() * W,
1198 |       y: Math.random() * H,
1199 |       vx: (Math.random() - 0.5) * 0.4,
1200 |       vy: (Math.random() - 0.5) * 0.4,
1201 |       r: Math.random() * 2 + 1
1202 |     });
1203 |   }
1204 | 
1205 |   function draw() {
1206 |     ctx.clearRect(0, 0, W, H);
1207 |     // Update
1208 |     particles.forEach(p => {
1209 |       p.x += p.vx; p.y += p.vy;
1210 |       if (p.x < 0 || p.x > W) p.vx *= -1;
1211 |       if (p.y < 0 || p.y > H) p.vy *= -1;
1212 |     });
1213 |     // Lines
1214 |     for (let i = 0; i < N; i++) {
1215 |       for (let j = i + 1; j < N; j++) {
1216 |         const dx = particles[i].x - particles[j].x;
1217 |         const dy = particles[i].y - particles[j].y;
1218 |         const dist = Math.sqrt(dx*dx + dy*dy);
1219 |         if (dist < 140) {
1220 |           const alpha = (1 - dist / 140) * 0.35;
1221 |           ctx.beginPath();
1222 |           ctx.strokeStyle = `rgba(27,168,138,${alpha})`;
1223 |           ctx.lineWidth = 0.7;
1224 |           ctx.moveTo(particles[i].x, particles[i].y);
1225 |           ctx.lineTo(particles[j].x, particles[j].y);
1226 |           ctx.stroke();
1227 |         }
1228 |       }
1229 |     }
1230 |     // Dots
1231 |     particles.forEach(p => {
1232 |       ctx.beginPath();
1233 |       ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
1234 |       ctx.fillStyle = 'rgba(27,168,138,0.5)';
1235 |       ctx.fill();
1236 |     });
1237 |     requestAnimationFrame(draw);
1238 |   }
1239 |   draw();
1240 | }
